import { NEEDS, STATUS, assessIsolation, evaluateProgram, allowedTransitions, validateTransition, createDemoCases } from './domain.js';

const $ = (selector, root=document) => root.querySelector(selector);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = (url) => { try { const u = new URL(url); return ['https:','http:'].includes(u.protocol) ? u.href : '#'; } catch { return '#'; } };
const TODAY = new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const STORE = 'ieum-map-mvp:v1';
